selector_to_html = {"a[href=\"#install-from-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Install from source<a class=\"headerlink\" href=\"#install-from-source\" title=\"Link to this heading\">#</a></h2><p>This section covers installing vllm-plugin-FL and its dependencies from source code.</p>", "a[href=\"run-inference-task.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Run an inference task<a class=\"headerlink\" href=\"#run-an-inference-task\" title=\"Link to this heading\">#</a></h1><p>With vLLM and vllm-plugin-FL installed, you can run inference in two ways: offline batched inference (load the model directly in a Python script) or serving inference (start an API server and send requests). Choose the approach that fits your use case.</p>", "a[href=\"example-qwen2.5-bv150.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Qwen2.5-1.5B inference on Iluvatar BI-V150<a class=\"headerlink\" href=\"#qwen2-5-1-5b-inference-on-iluvatar-bi-v150\" title=\"Link to this heading\">#</a></h1><h2>Contents<a class=\"headerlink\" href=\"#contents\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#hygon-dcu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Hygon DCU<a class=\"headerlink\" href=\"#hygon-dcu\" title=\"Link to this heading\">#</a></h3><p>Available for vllm-plugin-FL v0.2.0 (vLLM 0.20.0).</p>", "a[href=\"../overview/overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">vllm-plugin-FL Overview<a class=\"headerlink\" href=\"#vllm-plugin-fl-overview\" title=\"Link to this heading\">#</a></h1><p>vllm-plugin-FL is a plugin for the <a class=\"reference external\" href=\"https://github.com/vllm-project/vllm\">vLLM</a> inference/serving framework, built on FlagOS\u2019s unified multi-chip backend \u2014 including the unified operator library <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems\">FlagGems</a> and the unified communication library <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagCX\">FlagCX</a>. It extends vLLM\u2019s capabilities and performance across diverse hardware environments. Without changing vLLM\u2019s original interfaces or usage patterns, the same command can run model inference/serving on different chips.</p>", "a[href=\"../dispatch_user_guide/configure-backend-selection.html#environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment variables<a class=\"headerlink\" href=\"#environment-variables\" title=\"Link to this heading\">#</a></h2><p>Environment variables can override specific items from platform config. If not set, values from platform config file are used.</p>", "a[href=\"#iluvatar-bi-v150\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Iluvatar BI-V150<a class=\"headerlink\" href=\"#iluvatar-bi-v150\" title=\"Link to this heading\">#</a></h3><p>Available for vllm-plugin-FL v0.1.0 (vLLM 0.13.0).</p>", "a[href=\"#optional-dispatch-operators\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">(Optional) Dispatch operators<a class=\"headerlink\" href=\"#optional-dispatch-operators\" title=\"Link to this heading\">#</a></h2><p>If needed, you can also dispatch operators.</p><p>For concept related information, see <a class=\"reference internal\" href=\"../overview/overview.html\"><span class=\"std std-doc\">vllm-plugin-FL Overview</span></a>.\nFor configuration related information, see <a class=\"reference internal\" href=\"../dispatch_user_guide/dispatch-user-guide.html\"><span class=\"std std-doc\">Operator dispatch user guide</span></a>.</p>", "a[href=\"#install-software-for-running-an-inference-task\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install software for running an inference task<a class=\"headerlink\" href=\"#install-software-for-running-an-inference-task\" title=\"Link to this heading\">#</a></h1><p>vllm-plugin-FL can be installed from source code or via Docker images.</p>", "a[href=\"#install-from-docker-image\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Install from docker image<a class=\"headerlink\" href=\"#install-from-docker-image\" title=\"Link to this heading\">#</a></h2><p>This section covers running vllm-plugin-FL using pre-built Docker images.</p>", "a[href=\"../dispatch_user_guide/dispatch-user-guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Operator dispatch user guide<a class=\"headerlink\" href=\"#operator-dispatch-user-guide\" title=\"Link to this heading\">#</a></h1><p>This guide describes how to use an operator dispatch system that selects between FlagGems, vendor-specific, and PyTorch reference implementations. The selection follows a priority hierarchy, from highest to lowest:</p>", "a[href=\"#svt-full-stack-test-images-v0-2-0-rc2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">SVT Full-Stack Test Images (v0.2.0-rc2)<a class=\"headerlink\" href=\"#svt-full-stack-test-images-v0-2-0-rc2\" title=\"Link to this heading\">#</a></h3><p>Pre-built SVT images with full FlagOS stack:</p>", "a[href=\"#use-native-cuda-operators\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Use native CUDA operators<a class=\"headerlink\" href=\"#use-native-cuda-operators\" title=\"Link to this heading\">#</a></h4><p>If you want to use the original CUDA operators, you can set the following environment variables.</p>", "a[href=\"#nvidia\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">NVIDIA<a class=\"headerlink\" href=\"#nvidia\" title=\"Link to this heading\">#</a></h3><p>Available for vllm-plugin-FL v0.2.0 (vLLM 0.20.2).</p>", "a[href=\"#optional-additional-setup-for-cuda\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\uff08Optional\uff09Additional setup for CUDA<a class=\"headerlink\" href=\"#optional-additional-setup-for-cuda\" title=\"Link to this heading\">#</a></h3><p>This section illustrates how to run an inference task with CUDA through setting environment variables.</p><p>For operator dispatch environment variables, see <a class=\"reference internal\" href=\"../dispatch_user_guide/configure-backend-selection.html#environment-variables\"><span class=\"std std-ref\">Environment variables</span></a>.</p>", "a[href=\"#additional-setup-for-huawei-ascend\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Additional setup for Huawei Ascend<a class=\"headerlink\" href=\"#additional-setup-for-huawei-ascend\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#use-cuda-communication-library\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Use CUDA communication library<a class=\"headerlink\" href=\"#use-cuda-communication-library\" title=\"Link to this heading\">#</a></h4><p>This section demonstrates how to run an inference task with CUDA by setting environment variables.</p>", "a[href=\"#huawei-ascend\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Huawei Ascend<a class=\"headerlink\" href=\"#huawei-ascend\" title=\"Link to this heading\">#</a></h3><p>Available for vllm-plugin-FL v0.1.0 (vLLM 0.13.0).</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
